349	// ---------------------------------------------------------------------------
350	// Movement deltas — "is this bot actually moving, or is it wedged?"
351	//
352	// Per-bot in-memory ring of timestamped positions, ~65s deep, appended on every
353	// fleet build (client-driven or self-poll alike). A delta is the straight-line
354	// 3D distance from the current position to the sample nearest N seconds ago —
355	// deliberately endpoint-to-endpoint, not path length: it answers "did it get
356	// anywhere", which is the wedge question, and costs one sqrt.
357	//
358	// The ring lives only in this process: it resets when the panel restarts, and
359	// survives browser refreshes (which is the point — the chief's tab being closed
360	// must not blank the history). See SELF_POLL_MS (panel.mjs) for how it stays warm.
361	// ---------------------------------------------------------------------------
362	const POS_RING_MS = 65_000;
363	// How far off the requested age a sample may be and still count. At the 5s
364	// self-poll cadence the nearest sample is normally within ~2.5s; anything
365	// beyond this means the ring is too young or has a hole, and the honest answer
366	// is null rather than a delta measured over the wrong window.
367	const DELTA_TOLERANCE_MS = 7_500;
368	const posRing = new Map(); // port -> [{ t, x, y, z }] oldest first
369	
370	function samplePosition(port, pos, now) {
371	  let ring = posRing.get(port);
372	  if (!ring) {
373	    ring = [];
374	    posRing.set(port, ring);
375	  }
376	  if (pos && typeof pos.x === 'number') ring.push({ t: now, x: pos.x, y: pos.y, z: pos.z });
377	  const cutoff = now - POS_RING_MS;
378	  while (ring.length && ring[0].t < cutoff) ring.shift();
379	  return ring;
380	}
381	
382	function deltaOver(ring, pos, now, windowMs) {
383	  if (!pos || typeof pos.x !== 'number') return null;
384	  const target = now - windowMs;
385	  let best = null;
386	  let bestGap = Infinity;
387	  for (const s of ring) {
388	    const gap = Math.abs(s.t - target);
389	    if (gap < bestGap) {
390	      bestGap = gap;
391	      best = s;
392	    }
393	  }
394	  // Covers the just-started case too: with only fresh samples in the ring the
395	  // nearest one is ~windowMs away from the target, so this returns null until
396	  // the ring is actually old enough to answer.
397	  if (!best || bestGap > DELTA_TOLERANCE_MS) return null;
398	  const dx = pos.x - best.x;
399	  const dy = pos.y - best.y;
400	  const dz = pos.z - best.z;
401	  return Math.round(Math.sqrt(dx * dx + dy * dy + dz * dz) * 10) / 10;
402	}
