404	async function buildFleet() {
405	  const bots = await Promise.all(PORTS.map((p) => pollBot(p).catch((err) => ({
406	    port: p,
407	    name: BOT_BY_PORT.get(p)?.name ?? `:${p}`,
408	    team: BOT_BY_PORT.get(p)?.team ?? 'white',
409	    color: TEAM_HEX[BOT_BY_PORT.get(p)?.team ?? 'white'] ?? TEAM_HEX.white,
410	    offline: true,
411	    offlineReason: err?.message ?? String(err),
412	    connected: false,
413	    pos: null, distance: null, health: null, food: null, inventory: [],
414	    currentTask: null, lastError: null, deathCount: null, idleGuard: null,
415	    lastDeath: null, engine: null,
416	    idle: false, taskStartedAt: null, events: [],
417	  }))));
418	
419	  // Feed the position ring and stamp each bot's deltas. Offline bots still get
420	  // a samplePosition() call (with a null pos) so their ring keeps getting
421	  // pruned rather than freezing stale samples that would produce a bogus delta
422	  // the moment the runner comes back.
423	  const now = Date.now();
424	  for (const b of bots) {
425	    const pos = b.offline ? null : b.pos;
426	    const ring = samplePosition(b.port, pos, now);
427	    b.delta30 = deltaOver(ring, pos, now, 30_000);
428	    b.delta60 = deltaOver(ring, pos, now, 60_000);
429	  }
430	
431	  const online = bots.filter((b) => !b.offline);
432	  const iron = bots.reduce((sum, b) => {
433	    const stack = b.inventory.find((i) => i.name === 'iron_ingot');
434	    return sum + (stack ? stack.count : 0);
435	  }, 0);
436	
437	  return {
438	    ts: new Date().toISOString(),
439	    quota: { iron_ingot: IRON_QUOTA },
440	    summary: {
441	      total: PORTS.length,
442	      online: online.length,
443	      idle: online.filter((b) => b.idle).length,
444	      iron_ingot: iron,
445	    },
446	    bots,
447	  };
448	}
