450	export async function getFleet() {
451	  const now = Date.now();
452	  if (fleetCache.payload && now - fleetCache.at < FLEET_CACHE_MS) return fleetCache.payload;
453	  // Collapse concurrent refreshes onto one poll — a hammered dashboard must not
454	  // multiply into N parallel pokes at every runner.
455	  if (!fleetInFlight) {
456	    const gen = fleetGen;
457	    fleetInFlight = buildFleet()
458	      .then((payload) => {
459	        if (gen === fleetGen) fleetCache = { at: Date.now(), payload };
460	        return payload;
461	      })
462	      .finally(() => {
463	        fleetInFlight = null;
464	      });
465	  }
466	  return fleetInFlight;
467	}
