475	const ALERT_PATHS = [path.join(HERE, 'logs', 'alerts.log'), path.join(HERE, 'alerts.log')];
476	const ALERT_TAIL_BYTES = 256 * 1024;
477	const ALERT_LINE_RE = /^\[([^\]]+)\]\s*(?:ALERT\s*)?(.*)$/;
