479	export async function readAlerts() {
480	  for (const file of ALERT_PATHS) {
481	    let handle = null;
482	    try {
483	      handle = await fsp.open(file, 'r');
484	      const { size } = await handle.stat();
485	      const start = Math.max(0, size - ALERT_TAIL_BYTES);
486	      const buf = Buffer.alloc(size - start);
487	      if (buf.length) await handle.read(buf, 0, buf.length, start);
488	      const lines = buf.toString('utf8').split(/\r?\n/).filter((l) => l.trim());
489	      // A partial first line is possible when the tail window cut mid-line.
490	      if (start > 0) lines.shift();
491	      return {
492	        file,
493	        alerts: lines.slice(-ALERT_LINES).reverse().map((line) => {
494	          const m = ALERT_LINE_RE.exec(line);
495	          return m ? { ts: m[1], msg: m[2] } : { ts: null, msg: line };
496	        }),
497	      };
498	    } catch {
499	      // try the next candidate path
500	    } finally {
501	      await handle?.close().catch(() => {});
502	    }
503	  }
504	  return { file: null, alerts: [] };
