507	// ---------------------------------------------------------------------------
508	// TODO board — parses cave/TODO.md's markdown tables server-side (round 5,
509	// team-lead's phase-2 ask) so the page can show "what is the tribe working
510	// on" without shipping a markdown parser to the client. Cached on the file's
511	// mtime: re-read+re-parse only when TODO.md actually changed, not on every
512	// poll — driver edits to that file are occasional, not per-second.
513	//
514	// TODO.md carries at least two tables in practice: the live board (#, Lane,
515	// Task, Who, Status columns) and a "## DONE" section further down (Task, By
516	// — no Status column, since everything in it is implicitly done). Both are
517	// parsed the same generic way — by header name, not position — so a
518	// hand-reordered or renamed column still lands in the right field, and a
519	// row whose cell count doesn't match its header is counted and skipped
520	// rather than guessed at or thrown on.
521	// ---------------------------------------------------------------------------
522	const TODO_PATH = path.join(HERE, 'TODO.md');
523	let todoCache = { mtimeMs: -1, board: null };
524	
525	const TODO_COLUMN_ALIASES = { lane: 'lane', task: 'task', who: 'who', by: 'who', status: 'status' };
526	
527	function splitTableRow(line) {
528	  // GFM allows the leading/trailing pipe to be omitted; strip them if
529	  // present so "| a | b |" and "a | b" split identically.
530	  return line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
531	}
532	
533	function isTableSeparatorRow(line) {
534	  const t = line.trim();
535	  return t.length > 0 && /^[-:|\s]+$/.test(t) && t.includes('-');
536	}
537	
538	export function parseTodoMarkdown(text) {
539	  const lines = text.split(/\r?\n/);
540	  const rows = [];
541	  let skipped = 0;
542	  let lastHeading = '';
543	
544	  for (let i = 0; i < lines.length; i++) {
545	    const line = lines[i];
546	    if (/^#{1,6}\s/.test(line)) {
547	      lastHeading = line.replace(/^#{1,6}\s*/, '').trim();
548	      continue;
549	    }
550	    if (!line.includes('|') || i + 1 >= lines.length || !isTableSeparatorRow(lines[i + 1])) continue;
551	
552	    // line i is a table header, i+1 its separator.
553	    const header = splitTableRow(line).map((h) => h.toLowerCase());
554	    const fieldFor = header.map((h) => TODO_COLUMN_ALIASES[h] ?? null);
555	    if (!fieldFor.includes('task')) {
556	      // Not one of ours (no recognizable Task column) — skip just the
557	      // separator row and keep scanning; whatever body rows follow aren't
558	      // touched since we never entered the body-parsing loop below.
559	      i += 1;
560	      continue;
561	    }
562	    // Status-less tables (the "## DONE" section: Task, By) default every row
563	    // in them to 'done' rather than 'todo' — matching the heading they sit
564	    // under, not guessing from row content.
565	    const doneSection = /^done\b/i.test(lastHeading);
566	    i += 2; // past header + separator, onto the first body row
567	    while (i < lines.length && lines[i].trim().startsWith('|')) {
568	      const cells = splitTableRow(lines[i]);
569	      if (cells.length !== header.length) {
570	        skipped++;
571	        i++;
572	        continue;
573	      }
574	      const rec = { lane: '', task: '', who: '', status: '' };
575	      fieldFor.forEach((field, idx) => {
576	        if (field) rec[field] = cells[idx] || '';
577	      });
578	      if (!rec.task) {
579	        skipped++;
580	        i++;
581	        continue;
582	      }
583	      if (!rec.status) rec.status = doneSection ? 'done' : 'todo';
584	      rows.push(rec);
585	      i++;
586	    }
587	    i--; // back up one so the outer for-loop's i++ lands on the line we just stopped at
588	  }
589	  return { rows, skipped };
590	}
591	
592	function classifyStatus(status) {
593	  if (/^doing\b/i.test(status)) return 'doing';
594	  if (/^done\b/i.test(status)) return 'done';
595	  return 'todo';
596	}
597	
598	// Strips a leading doing/done/todo keyword — redundant once a row is already
599	// grouped under that bucket's own heading. Only the bare keyword (plus an
600	// optional trailing dash) goes; "queued", "queued after #5", "blocked on
601	// cobble", "law" etc. don't match this and stay verbatim, since those ARE
602	// real information the bucket label alone doesn't carry.
603	function bucketDetail(status) {
604	  return status.replace(/^(doing|done|todo)\b\s*[-—:]*\s*/i, '').trim();
605	}
606	
607	// A who-token that case-insensitively matches a roster bot gets that bot's
608	// team colour client-side — same visual language as its own card's name.
609	// Everything else (a driver/teammate name, "orchestrator", loose prose like
610	// "pair drivers") renders as a plain chip: real information, just not a bot.
611	function whoChip(token) {
612	  const bot = BOT_BY_NAME.get(token.toLowerCase());
613	  return { name: token, color: bot ? TEAM_HEX[bot.team] ?? null : null };
614	}
615	
616	function splitWho(who) {
617	  return who.split(/[,+]/).map((s) => s.trim()).filter(Boolean).map(whoChip);
618	}
619	
620	function buildTodoBoard(parsed) {
621	  const board = { doing: [], todo: [], done: [] };
622	  for (const rec of parsed.rows) {
623	    const bucket = classifyStatus(rec.status);
624	    board[bucket].push({
625	      lane: rec.lane,
626	      task: rec.task,
627	      who: splitWho(rec.who),
628	      detail: bucketDetail(rec.status),
629	    });
630	  }
631	  return board;
632	}
633	
634	export async function getTodoBoard() {
635	  let stat;
636	  try {
637	    stat = await fsp.stat(TODO_PATH);
638	  } catch (err) {
639	    return { ok: false, error: `TODO.md unreadable (${err?.code ?? err?.message ?? err})`, doing: [], todo: [], done: [], skipped: 0, total: 0 };
640	  }
641	  if (todoCache.board && todoCache.mtimeMs === stat.mtimeMs) return todoCache.board;
642	  let text;
643	  try {
644	    text = await fsp.readFile(TODO_PATH, 'utf8');
645	  } catch (err) {
646	    return { ok: false, error: err?.message ?? String(err), doing: [], todo: [], done: [], skipped: 0, total: 0 };
647	  }
648	  const parsed = parseTodoMarkdown(text);
649	  const board = buildTodoBoard(parsed);
650	  const result = { ok: true, doing: board.doing, todo: board.todo, done: board.done, skipped: parsed.skipped, total: parsed.rows.length };
651	  todoCache = { mtimeMs: stat.mtimeMs, board: result };
652	  return result;
653	}
