656	// Vault — round 7 (team-lead's ask): renders cave/audit-snapshot.json, the
657	// ground-truth depot ledger `cave/audit.mjs` writes after a read-only chest
658	// walk. Same mtime-cache shape as the TODO board above, with one addition:
659	// snapshot AGE must never be baked into the cached object, since the whole
660	// point of "cache until the file changes" is that the file can go stale for
661	// a long time between audit runs while this endpoint keeps getting polled —
662	// so age is computed fresh on every call, cache hit or not.
663	//
664	// CHEST_META (id -> x/y/z/label) is mirrored from audit.mjs's own CHESTS
665	// list (~line 36) — audit.mjs is a one-shot CLI script with no module
666	// exports (it calls main() directly), so this is a hand-synced copy, same
667	// contract as the BOTS/TEAM_HEX tables above. Keep in sync when a chest
668	// moves, gets added, or is removed from BASE.md's registry.
669	// ---------------------------------------------------------------------------
670	const VAULT_PATH = path.join(HERE, 'audit-snapshot.json');
671	const VAULT_STALE_MS = 2 * 60 * 60 * 1000;
672	let vaultCache = { mtimeMs: -1, result: null };
673	
674	const CHEST_META = {
675	  chest_a_materials: { x: 11, y: 89, z: 55, label: 'chest A (wood/materials depot)' },
676	  chest_b_tools: { x: 12, y: 90, z: 54, label: 'chest B (building/torch supplies)' },
677	  chest_c_food: { x: 16, y: 89, z: 54, label: 'chest C (food, Mine House)' },
678	  chest_d_ore: { x: 14, y: 89, z: 57, label: 'chest D (ore, Mine House)' },
679	};
680	
681	function buildVaultChests(rawChests) {
682	  return Object.entries(rawChests ?? {}).map(([id, counts]) => {
683	    const meta = CHEST_META[id] ?? null;
684	    const pos = meta ? { x: meta.x, y: meta.y, z: meta.z } : null;
685	    const label = meta?.label ?? id;
686	    // audit.mjs's __error shape: a chest it failed to read (goto/eval error,
687	    // chest missing/moved, timeout) — never a valid count map, so checked
688	    // first and rendered as a distinct failure, not garbage item chips.
689	    if (counts && typeof counts.__error === 'string') {
690	      return { id, label, pos, error: counts.__error, items: [], total: 0 };
691	    }
692	    const items = Object.entries(counts ?? {})
693	      .map(([name, count]) => ({ name, count }))
694	      .sort((a, b) => b.count - a.count);
695	    const total = items.reduce((sum, it) => sum + it.count, 0);
696	    return { id, label, pos, error: null, items, total };
697	  });
698	}
