700	export async function getVault() {
701	  let stat;
702	  try {
703	    stat = await fsp.stat(VAULT_PATH);
704	  } catch (err) {
705	    // ENOENT (audit.mjs has simply never been run yet) is the normal,
706	    // expected case — distinct from any other stat failure (permissions,
707	    // etc.), which IS worth surfacing rather than quietly treating as
708	    // "nothing to show".
709	    if (err?.code === 'ENOENT') return { ok: true, missing: true };
710	    return { ok: false, missing: false, error: `audit-snapshot.json unreadable (${err?.code ?? err?.message ?? err})` };
711	  }
712	
713	  let cached = vaultCache.result;
714	  if (!cached || vaultCache.mtimeMs !== stat.mtimeMs) {
715	    let raw;
716	    try {
717	      raw = await fsp.readFile(VAULT_PATH, 'utf8');
718	    } catch (err) {
719	      return { ok: false, missing: false, error: err?.message ?? String(err) };
720	    }
721	    let snapshot;
722	    try {
723	      snapshot = JSON.parse(raw);
724	    } catch (err) {
725	      return { ok: false, missing: false, error: `audit-snapshot.json corrupt JSON: ${err?.message ?? err}` };
726	    }
727	    cached = {
728	      ok: true,
729	      missing: false,
730	      ts: typeof snapshot.ts === 'string' ? snapshot.ts : null,
731	      botName: snapshot.botName ?? null,
732	      chests: buildVaultChests(snapshot.chests),
733	    };
734	    vaultCache = { mtimeMs: stat.mtimeMs, result: cached };
735	  }
736	
737	  const ageMs = cached.ts ? Date.now() - Date.parse(cached.ts) : null;
738	  return { ...cached, ageMs, staleMs: VAULT_STALE_MS };
739	}
