792	// Economy graphs (PANEL_V3_SPEC.md §3.2) — per-item, time-bucketed net-flow
793	// series over cave/ledger/*.jsonl for the wall-state sparkline row. Wired
794	// into GET /api/economy (panel.mjs), consumed by panel-client.js's Economy
795	// section — the ledger reader above (readLedgerEntries) is no longer
796	// unwired as of this round; readDeathFiles/readFelRelation below remain
797	// unwired, waiting on the Tribe Stat Wall.
798	//
799	// ECONOMY_KEY_ITEMS is a fixed, explicit allowlist (task brief's own six
800	// items) rather than "top N by ledger volume" — a stable sparkline row set
801	// that means the same thing every time it renders beats one that reshuffles
802	// as the tribe's economy shifts. An item on the list with zero movement in
803	// the window is simply omitted (never a fabricated flat-zero row) — same
804	// "never guess, never fabricate" contract as every other v3 primitive.
805	// ---------------------------------------------------------------------------
806	export const ECONOMY_KEY_ITEMS = ['iron_ingot', 'raw_iron', 'wheat', 'bread', 'oak_log', 'cobblestone'];
807	const ECONOMY_WINDOW_MS = 6 * 60 * 60 * 1000; // 6h
808	const ECONOMY_BUCKET_MS = 10 * 60 * 1000; // 10min
809	const ECONOMY_BUCKET_COUNT = ECONOMY_WINDOW_MS / ECONOMY_BUCKET_MS; // 36
