811	// Parsed-entries cache, keyed on the ledger directory's newest file mtime
812	// (generalizing /api/todo's single-file mtime check to N files, per the
813	// architecture note's own recommendation) plus the sorted file list, so a
814	// file being added/removed also busts the cache even on the rare tie where
815	// it wouldn't otherwise move the max mtime. Re-reads all files only when the
816	// directory actually changed, not on every /api/economy poll.
817	let economyEntriesCache = { sigKey: null, entries: null };
818	
819	async function getLedgerEntriesCached() {
820	  let files;
821	  try {
822	    files = (await fsp.readdir(LEDGER_DIR)).filter((f) => f.endsWith('.jsonl'));
823	  } catch {
824	    return { entries: null, files: [] }; // no ledger/ dir at all — distinct from "dir exists, empty"
825	  }
826	  if (!files.length) return { entries: [], files: [] };
827	  let newest = 0;
828	  for (const f of files) {
829	    try {
830	      const stat = await fsp.stat(path.join(LEDGER_DIR, f));
831	      if (stat.mtimeMs > newest) newest = stat.mtimeMs;
832	    } catch {
833	      // vanished between readdir and stat — readLedgerEntries()'s own
834	      // per-file try/catch below tolerates this exact race too.
835	    }
836	  }
837	  const sigKey = `${newest}|${files.slice().sort().join(',')}`;
838	  if (economyEntriesCache.entries && economyEntriesCache.sigKey === sigKey) {
839	    return { entries: economyEntriesCache.entries, files };
840	  }
841	  const { entries } = await readLedgerEntries();
842	  economyEntriesCache = { sigKey, entries };
843	  return { entries, files };
844	}
