846	// Reads + buckets fresh on every call (the bucket boundaries are relative to
847	// "now", which moves every second — baking them into the mtime-keyed cache
848	// above would freeze the window at whatever "now" was when the ledger last
849	// changed, same lesson Vault's ageMs-computed-fresh split already teaches).
850	// The underlying parsed-entries read IS cached above, so this stays cheap.
851	export async function getEconomy() {
852	  const { entries, files } = await getLedgerEntriesCached();
853	  if (entries === null || !files.length) return { ok: true, missing: true };
854	
855	  const parsed = entries.filter((e) => typeof e.delta === 'number' && typeof e.item === 'string' && typeof e.ts === 'string');
856	  if (!parsed.length) {
857	    // Files exist (an unparsed correction line, or a brand-new empty file)
858	    // but nothing summable yet — the honest "leer" state, distinct from "no
859	    // files at all" above, which hides the section outright instead.
860	    return { ok: true, missing: false, empty: true, windowMs: ECONOMY_WINDOW_MS, bucketMs: ECONOMY_BUCKET_MS, buckets: ECONOMY_BUCKET_COUNT, items: [] };
861	  }
862	
863	  const now = Date.now();
864	  const cutoff = now - ECONOMY_WINDOW_MS;
865	
866	  const items = [];
867	  for (const item of ECONOMY_KEY_ITEMS) {
868	    const rows = parsed.filter((e) => {
869	      const t = Date.parse(e.ts);
870	      return e.item === item && Number.isFinite(t) && t >= cutoff && t <= now;
871	    });
872	    if (!rows.length) continue; // no movement for this item in-window — omit, don't render a flat-zero row
873	    const buckets = new Array(ECONOMY_BUCKET_COUNT).fill(0);
874	    let net = 0;
875	    let lastTs = null;
876	    for (const r of rows) {
877	      const t = Date.parse(r.ts);
878	      const age = now - t;
879	      // Oldest bucket first (index 0), newest last — standard left-to-right
880	      // sparkline reading order. Clamped defensively against the exact-edge
881	      // case (age === windowMs) landing one past the last valid index.
882	      const idx = ECONOMY_BUCKET_COUNT - 1 - Math.min(ECONOMY_BUCKET_COUNT - 1, Math.floor(age / ECONOMY_BUCKET_MS));
883	      buckets[idx] += r.delta;
884	      net += r.delta;
885	      if (lastTs === null || t > Date.parse(lastTs)) lastTs = r.ts;
886	    }
887	    items.push({ item, net, lastTs, buckets });
888	  }
889	
890	  // items can legitimately be empty here even though parsed.length > 0 — real
891	  // ledger movement exists, just not for any tracked item in-window. That is
892	  // a different honest fact from "ledger leer" (empty:true above) and gets
893	  // its own client-side message rather than being folded into it.
894	  return { ok: true, missing: false, empty: false, windowMs: ECONOMY_WINDOW_MS, bucketMs: ECONOMY_BUCKET_MS, buckets: ECONOMY_BUCKET_COUNT, items };
895	}
