997	export async function getMissionsForBot(nameOrPort) {
998	  const name = resolveBotName(nameOrPort);
999	  if (!name) {
1000	    return { ok: false, missing: false, bot: null, error: `unknown bot "${nameOrPort}"`, entries: [] };
1001	  }
1002	  const file = path.join(MISSIONS_DIR, `${name}.jsonl`);
1003	  let text;
1004	  try {
1005	    text = await fsp.readFile(file, 'utf8');
1006	  } catch (err) {
1007	    if (err?.code === 'ENOENT') return { ok: true, missing: true, bot: name, entries: [] };
1008	    return { ok: false, missing: false, bot: name, error: err?.message ?? String(err), entries: [] };
1009	  }
1010	  const parsed = [];
1011	  let badLines = 0;
1012	  for (const line of text.split('\n')) {
1013	    if (!line.trim()) continue;
1014	    try {
1015	      parsed.push(JSON.parse(line));
1016	    } catch {
1017	      badLines++; // corrupt JSONL line — counted, not fatal
1018	    }
1019	  }
1020	  // Append-only file: later lines are newer. Reversing the parse order for
1021	  // "newest first" rather than sorting on each entry's own `ts` means one
1022	  // line with a missing/malformed timestamp can never jump the queue.
1023	  const newestFirst = parsed.slice().reverse();
1024	  return {
1025	    ok: true,
1026	    missing: false,
1027	    bot: name,
1028	    entries: newestFirst.slice(0, MISSION_HISTORY_CAP),
1029	    total: parsed.length,
1030	    badLines,
1031	  };
1032	}
