1120	// A chest with a read error (__error-shaped, see buildVaultChests) is
1121	// excluded from the sum rather than guessed at — the honest total is "what
1122	// we could actually confirm", which can under-count vs. reality when a chest
1123	// goto/eval failed, same tradeoff Vault's own per-chest error display makes.
1124	function vaultTile(vault, names) {
1125	  if (!vault || vault.missing) return { ok: true, missing: true };
1126	  if (vault.ok === false) return { ok: false, missing: false, error: vault.error };
1127	  let total = 0;
1128	  for (const chest of vault.chests || []) {
1129	    if (chest.error) continue;
1130	    for (const it of chest.items || []) {
1131	      if (names.includes(it.name)) total += it.count;
1132	    }
1133	  }
1134	  return { ok: true, missing: false, total, ageMs: vault.ageMs, staleMs: vault.staleMs };
1135	}
