1196	export async function doWake(botArg) {
1197	  const bot = resolveBot(botArg);
1198	  if (!bot) return { status: 404, body: { ok: false, error: `unknown bot "${botArg}" (not on this panel's port list)` } };
1199	
1200	  const plan = bot.wake ?? FALLBACK_WAKE;
1201	  // force:false is built here, not copied from the plan and not read from the
1202	  // request — there is no code path in this file that can send force:true.
1203	  // source:'panel' tags the runner's own task/event log with who actually
1204	  // pushed this (issue #6 arbitration forensics) — previously indistinguishable
1205	  // from any other unidentified HTTP caller (runner.js defaults body.source
1206	  // to 'http' when absent).
1207	  const body = { ...plan.body, force: false, source: 'panel' };
1208	
1209	  try {
1210	    const { status, json } = await postJson(`http://127.0.0.1:${bot.port}${plan.ep}`, body);
1211	    if (status === 409) {
1212	      return {
1213	        status: 200,
1214	        body: {
1215	          ok: false,
1216	          busy: true,
1217	          message: 'busy, not preempted',
1218	          bot: bot.name,
1219	          currentTask: json?.currentTask ?? null,
1220	        },
1221	      };
1222	    }
1223	    if (status !== 200) {
1224	      return {
1225	        status: 200,
1226	        body: { ok: false, bot: bot.name, error: json?.error ?? `runner HTTP ${status}`, httpStatus: status },
1227	      };
1228	    }
1229	    return {
1230	      status: 200,
1231	      body: {
1232	        ok: true,
1233	        bot: bot.name,
1234	        port: bot.port,
1235	        pushed: { ep: plan.ep, body, say: plan.say },
1236	        task: json?.task ?? null,
1237	      },
1238	    };
1239	  } catch (err) {
1240	    return { status: 200, body: { ok: false, bot: bot.name, error: err?.message ?? String(err) } };
1241	  }
1242	}
