1244	export async function doStop(botArg) {
1245	  const bot = resolveBot(botArg);
1246	  if (!bot) return { status: 404, body: { ok: false, error: `unknown bot "${botArg}" (not on this panel's port list)` } };
1247	  try {
1248	    const { status, json } = await postJson(`http://127.0.0.1:${bot.port}/stop`, {});
1249	    if (status !== 200) {
1250	      return { status: 200, body: { ok: false, bot: bot.name, error: json?.error ?? `runner HTTP ${status}`, httpStatus: status } };
1251	    }
1252	    return { status: 200, body: { ok: true, bot: bot.name, port: bot.port, task: json?.task ?? null } };
1253	  } catch (err) {
1254	    return { status: 200, body: { ok: false, bot: bot.name, error: err?.message ?? String(err) } };
