 47	// PANEL_PORT defaults to the production 3200; override with env for a
 48	// throwaway dev instance (e.g. PANEL_PORT=3290) so panel changes can be
 49	// smoke-tested without ever touching the live process on 3200. The Host
 50	// allow-list below is built off this const, so a dev instance automatically
 51	// allow-lists its own port instead of 3200's.
 52	const PANEL_PORT = Number(process.env.PANEL_PORT) || 3200;
 53	// Bind all interfaces: loopback + Tailscale (chief order 2026-09-01). Network
 54	// exposure is fenced by the Windows firewall (inbound 3200 scoped to the
 55	// tailnet CGNAT range 100.64.0.0/10) — the Host allow-list below stays as
 56	// CSRF protection, not as network auth.
 57	const PANEL_HOST = process.env.PANEL_HOST || '0.0.0.0';
 58	// The panel polls the fleet on its own timer, whether or not a browser is
 59	// attached. Movement deltas are only meaningful if the position ring has been
 60	// filling all along, so the page must not be the thing that drives sampling —
 61	// otherwise opening the tab shows dashes for the first minute. Request serving
 62	// still goes through panel-data.mjs's own fleet cache; this just keeps it warm.
 63	const SELF_POLL_MS = 5000;
