 65	// ---------------------------------------------------------------------------
 66	// /panel.js — the client script, served as a real static file (architecture
 67	// note, phase 1). mtime-cached in memory the same spirit as panel-data.mjs's
 68	// TODO/Vault caches: re-read from disk only when the file on disk actually
 69	// changed, not on every request.
 70	// ---------------------------------------------------------------------------
 71	const PANEL_CLIENT_PATH = path.join(HERE, 'panel-client.js');
 72	let clientCache = { mtimeMs: -1, text: null };
 73	
 74	async function getClientScript() {
 75	  const stat = await fsp.stat(PANEL_CLIENT_PATH);
 76	  if (!clientCache.text || clientCache.mtimeMs !== stat.mtimeMs) {
 77	    clientCache = { mtimeMs: stat.mtimeMs, text: await fsp.readFile(PANEL_CLIENT_PATH, 'utf8') };
 78	  }
 79	  return clientCache.text;
 80	}
