 82	// ---------------------------------------------------------------------------
 83	// HTTP plumbing
 84	// ---------------------------------------------------------------------------
 85	
 86	function sendJson(res, status, obj) {
 87	  const body = JSON.stringify(obj);
 88	  res.writeHead(status, {
 89	    'content-type': 'application/json; charset=utf-8',
 90	    'content-length': Buffer.byteLength(body),
 91	    'cache-control': 'no-store',
 92	  });
 93	  res.end(body);
 94	}
 95	
 96	function readBody(req) {
 97	  return new Promise((resolve, reject) => {
 98	    let data = '';
 99	    req.on('data', (chunk) => {
100	      data += chunk;
101	      if (data.length > 64_000) req.destroy(new Error('body too large'));
102	    });
103	    req.on('end', () => {
104	      if (!data) return resolve({});
105	      try {
106	        resolve(JSON.parse(data));
107	      } catch {
108	        reject(new Error('invalid JSON body'));
109	      }
110	    });
111	    req.on('error', reject);
112	  });
113	}
114	
115	const server = http.createServer((req, res) => {
116	  handle(req, res).catch((err) => {
117	    try {
118	      sendJson(res, 500, { error: err?.message ?? String(err) });
119	    } catch {
120	      // response already gone
121	    }
122	  });
123	});
124	
125	// CSRF / DNS-rebinding guard. Binding to 127.0.0.1 keeps other machines out
126	// but does NOT keep out a random web page the operator happens to have open:
127	// the browser will happily issue cross-origin requests at localhost. Two
128	// layers close that, and both are needed:
129	//
130	//  1. Host allow-list — a hostile page can point a domain it controls at
131	//     127.0.0.1 (DNS rebinding) and reach this server with its own origin's
132	//     privileges. Such a request still carries that attacker hostname in the
133	//     Host header, so anything but our own loopback names is refused.
134	//  2. Content-type gate on writes — text/plain, form-urlencoded and multipart
135	//     are CORS-"simple" request types: a page can POST them cross-origin with
136	//     no preflight at all, and `mode:'no-cors'` hides the response while the
137	//     mutation still lands. Requiring application/json forces a preflight,
138	//     and since this server sends no CORS headers the preflight fails and the
139	//     request never arrives.
140	const ALLOWED_HOSTS = new Set([
141	  `127.0.0.1:${PANEL_PORT}`,
142	  `localhost:${PANEL_PORT}`,
143	  `[::1]:${PANEL_PORT}`,
144	  `zetpc:${PANEL_PORT}`,
145	  `zetpc.tail5d7e78.ts.net:${PANEL_PORT}`,
146	]);
147	// Tailscale CGNAT IPs (100.64.0.0/10) are legitimate Host values when a
148	// tailnet device opens the panel by IP.
149	const TAILNET_HOST_RE = new RegExp('^100([.][0-9]{1,3}){3}:' + PANEL_PORT + '$');
150	
151	function hostAllowed(req) {
152	  const host = req.headers.host;
153	  if (typeof host !== 'string') return false;
154	  const h = host.toLowerCase();
155	  return ALLOWED_HOSTS.has(h) || TAILNET_HOST_RE.test(h);
156	}
157	
158	function isJsonRequest(req) {
159	  const ct = req.headers['content-type'];
160	  return typeof ct === 'string' && ct.split(';')[0].trim().toLowerCase() === 'application/json';
161	}
162	
163	async function handle(req, res) {
164	  const url = new URL(req.url, `http://${PANEL_HOST}:${PANEL_PORT}`);
165	  const p = url.pathname;
166	  const m = req.method;
167	
168	  if (!hostAllowed(req)) {
169	    return sendJson(res, 403, { error: 'forbidden host — panel only answers to its own loopback origin' });
170	  }
171	
172	  if (m === 'GET' && (p === '/' || p === '/index.html')) {
173	    const html = renderPage();
174	    res.writeHead(200, {
175	      'content-type': 'text/html; charset=utf-8',
176	      'content-length': Buffer.byteLength(html),
177	      'cache-control': 'no-store',
178	    });
179	    return res.end(html);
180	  }
181	
182	  if (m === 'GET' && p === '/panel.js') {
183	    let text;
184	    try {
185	      text = await getClientScript();
186	    } catch (err) {
187	      return sendJson(res, 500, { error: `panel-client.js unreadable (${err?.message ?? err})` });
188	    }
189	    res.writeHead(200, {
190	      'content-type': 'application/javascript; charset=utf-8',
191	      'content-length': Buffer.byteLength(text),
192	      'cache-control': 'no-store',
193	    });
194	    return res.end(text);
195	  }
196	
197	  if (m === 'GET' && p === '/api/fleet') {
198	    return sendJson(res, 200, await getFleet());
199	  }
200	
201	  if (m === 'GET' && p === '/api/alerts') {
202	    return sendJson(res, 200, await readAlerts());
203	  }
204	
205	  if (m === 'GET' && p === '/api/todo') {
206	    return sendJson(res, 200, await getTodoBoard());
207	  }
208	
209	  if (m === 'GET' && p === '/api/vault') {
210	    return sendJson(res, 200, await getVault());
211	  }
212	
213	  // Economy graphs (PANEL_V3_SPEC.md §3.2) — per-item, time-bucketed net-flow
214	  // series over cave/ledger/*.jsonl, decoupled from the fast /api/fleet poll
215	  // (panel-client.js fetches this on its own slower ~20s timer, see that
216	  // file's own comment — ledger files only change on deposit/withdraw
217	  // events, not sub-second like task status).
218	  if (m === 'GET' && p === '/api/economy') {
219	    return sendJson(res, 200, await getEconomy());
220	  }
221	
222	  // Mission Control drilldown (PANEL_V3_SPEC.md §3.1) — one bot's mission
223	  // history, fetched lazily when a card's drilldown is opened, deliberately
224	  // NOT part of /api/fleet's fast 3s payload (no reason to ship 8 bots' worth
225	  // of history on every poll when at most one card is expanded at a time).
226	  // Tribe Stat Wall (PANEL_V3_SPEC.md §3.3) — the five big-number tiles above
227	  // the fleet grid. One combined endpoint (deaths streak, Vault-derived ore/
228	  // bread, missions-today, FEL relation all read from disk, no runner poll)
229	  // rather than splitting across the fast/slow cadences §3.3 sketches — none
230	  // of these five sources changes sub-minute, so panel-client.js rides this
231	  // on the same slower timer as /api/economy instead of adding a third tier.
232	  if (m === 'GET' && p === '/api/statwall') {
233	    return sendJson(res, 200, await getStatWall());
234	  }
235	
236	  if (m === 'GET' && p === '/api/missions') {
237	    const bot = url.searchParams.get('bot');
238	    if (!bot) {
239	      return sendJson(res, 200, { ok: false, missing: false, bot: null, error: 'bot query param required', entries: [] });
240	    }
241	    return sendJson(res, 200, await getMissionsForBot(bot));
242	  }
243	
244	  if (m === 'POST' && (p === '/api/wake' || p === '/api/stop')) {
245	    // Checked before the body is even read, and long before anything is
246	    // forwarded to a runner: a rejected request never touches a bot.
247	    if (!isJsonRequest(req)) {
248	      return sendJson(res, 415, { ok: false, error: 'content-type must be application/json' });
249	    }
250	    let body;
251	    try {
252	      body = await readBody(req);
253	    } catch (err) {
254	      return sendJson(res, 400, { ok: false, error: err.message });
255	    }
256	    const out = p === '/api/wake' ? await doWake(body.bot) : await doStop(body.bot);
257	    // A write invalidates the cache so the next poll shows the new state.
258	    invalidateFleet();
259	    return sendJson(res, out.status, out.body);
260	  }
261	
262	  return sendJson(res, 404, { error: 'not found' });
263	}
