86	    86	function sendJson(res, status, obj) {
87	    87	  const body = JSON.stringify(obj);
88	    88	  res.writeHead(status, {
89	    89	    'content-type': 'application/json; charset=utf-8',
90	    90	    'content-length': Buffer.byteLength(body),
91	    91	    'cache-control': 'no-store',
92	    92	  });
93	    93	  res.end(body);
94	    94	}
95	    95	
96	    96	function readBody(req) {
97	    97	  return new Promise((resolve, reject) => {
98	    98	    let data = '';
99	    99	    req.on('data', (chunk) => {
100	   100	      data += chunk;
101	   101	      if (data.length > 64_000) req.destroy(new Error('body too large'));
102	   102	    });
103	   103	    req.on('end', () => {
104	   104	      if (!data) return resolve({});
105	   105	      try {
106	   106	        resolve(JSON.parse(data));
107	   107	      } catch {
108	   108	        reject(new Error('invalid JSON body'));
109	   109	      }
110	   110	    });
111	   111	    req.on('error', reject);
112	   112	  });
113	   113	}
