125	   125	// CSRF / DNS-rebinding guard. Binding to 127.0.0.1 keeps other machines out
126	   126	// but does NOT keep out a random web page the operator happens to have open:
127	   127	// the browser will happily issue cross-origin requests at localhost. Two
128	   128	// layers close that, and both are needed:
129	   129	//
130	   130	//  1. Host allow-list — a hostile page can point a domain it controls at
131	   131	//     127.0.0.1 (DNS rebinding) and reach this server with its own origin's
132	   132	//     privileges. Such a request still carries that attacker hostname in the
133	   133	//     Host header, so anything but our own loopback names is refused.
134	   134	//  2. Content-type gate on writes — text/plain, form-urlencoded and multipart
135	   135	//     are CORS-"simple" request types: a page can POST them cross-origin with
136	   136	//     no preflight at all, and `mode:'no-cors'` hides the response while the
137	   137	//     mutation still lands. Requiring application/json forces a preflight,
138	   138	//     and since this server sends no CORS headers the preflight fails and the
139	   139	//     request never arrives.
140	   140	const ALLOWED_HOSTS = new Set([
141	   141	  `127.0.0.1:${PANEL_PORT}`,
142	   142	  `localhost:${PANEL_PORT}`,
143	   143	  `[::1]:${PANEL_PORT}`,
144	   144	  `zetpc:${PANEL_PORT}`,
145	   145	  `zetpc.tail5d7e78.ts.net:${PANEL_PORT}`,
146	   146	]);
147	   147	// Tailscale CGNAT IPs (100.64.0.0/10) are legitimate Host values when a
148	   148	// tailnet device opens the panel by IP.
149	   149	const TAILNET_HOST_RE = new RegExp('^100([.][0-9]{1,3}){3}:' + PANEL_PORT + '$');
150	   150	
151	   151	function hostAllowed(req) {
152	   152	  const host = req.headers.host;
153	   153	  if (typeof host !== 'string') return false;
154	   154	  const h = host.toLowerCase();
155	   155	  return ALLOWED_HOSTS.has(h) || TAILNET_HOST_RE.test(h);
156	   156	}
