395	    })
396	      .then(function (r) { return r.json(); })
397	      .then(function (j) {
398	        if (j.busy) { flash.className = 'flash bad'; flash.textContent = j.message || 'busy'; }
399	        else if (j.ok) { flash.className = 'flash'; flash.textContent = j.pushed ? ('pushed ' + j.pushed.ep) : 'stopped'; }
