  var key = String(bot.port);
  if (bot.kind === 'baritone') {
    var bc = cards[key] || (cards[key] = buildBaritoneCard());
    return paintBaritoneCard(bc, bot);
  }
  var c = cards[key] || (cards[key] = build(bot));

