function fmtDur(ms) {
  if (ms == null || !isFinite(ms) || ms < 0) return '';
  var s = Math.floor(ms / 1000);
  if (s < 60) return s + 's';
  var m = Math.floor(s / 60);
  if (m < 60) return m + 'm ' + (s % 60) + 's';
  var h = Math.floor(m / 60);
  return h + 'h ' + (m % 60) + 'm';
}
function toolSignature(heldItem) {
  if (heldItem === undefined) return 'undef';
  if (heldItem === null) return 'empty';
  var d = heldItem.durability;
  return heldItem.name + ':' + heldItem.count + ':' + (d ? d.used + '/' + d.max : '');
}
function renderToolText(heldItem) {
  if (heldItem === undefined) return 'HIDDEN (no G1 data)';
  if (heldItem === null) return 'shown: empty hand';
  var d = heldItem.durability;
  var out = 'shown: icon+name=' + heldItem.name;
