    var color = remaining >= 0.30 ? 'green' : (remaining >= 0.10 ? 'amber' : 'red');
    out += ' | durability ' + Math.max(0, d.max - d.used) + '/' + d.max + ' (' + (remaining*100).toFixed(0) + '% remaining, ' + color + ')';
